mapper.update:
UPDATE Carts
SET quantity = #{quantity}
WHERE cart_idx = #{cartIdx}

UPDATE Carts c
SET c.quantity = c.quantity + #{quantity}
WHERE c.cart_idx = #{cartIdx}
	AND(
		SELECT po.stock
		FROM ProductOption po
		WHERE po.option_idx = c.option_idx    	    
	) >= (c.quantity + #{quantity})

mapper.select:
SELECT 
    cart_idx AS cartIdx, 
    quantity
FROM Carts
WHERE user_idx = #{userIdx}
  AND product_idx = #{productIdx}
  AND option_idx = #{optionIdx}

mapper.delete:
DELETE FROM Carts 
WHERE cart_idx IN 

    #{item}
